namespace sv_c57cae8a705b489ab7c4b10068913695.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Each user gets their own instance, so selections are independent.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<Warehouse> AvailableWarehouses =
    [
        new("wh-a", "Warehouse A — East"),
        new("wh-b", "Warehouse B — West"),
        new("wh-c", "Warehouse C — Central"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public Warehouse CurrentWarehouse =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId);

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
            await OnWarehouseChanged.Invoke();
    }
}

public sealed record Warehouse(string Id, string Name);

namespace sv_c57cae8a705b489ab7c4b10068913695.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and broadcasts
/// updates to all subscribed components within the same circuit.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int LastKnownCount { get; private set; }

    /// <summary>
    /// Fired after new alert data arrives so every subscriber can re-render.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call; returns 0–15.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches the latest count and broadcasts to all subscribers.
    /// Called by the polling component; every other subscribed component
    /// receives the notification automatically.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LastKnownCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }
}

