@using sv_c57cae8a705b489ab7c4b10068913695.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">
    Currently viewing: <strong>@WarehouseState.CurrentWarehouse.Name</strong>
</p>

<div class="card" style="max-width:24rem;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4 @CountClass">@AlertService.LastKnownCount</p>
        <p class="text-muted">items below minimum level</p>
        <small class="text-muted">Auto-refreshes every 10 seconds while this page is open.</small>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private string CountClass => AlertService.LastKnownCount > 0 ? "text-danger" : "text-success";

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;

        // Fetch immediately, then start the polling loop.
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        StartPolling();
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
        }
        catch (OperationCanceledException) { /* expected on dispose or warehouse switch */ }
    }

    private async Task HandleWarehouseChanged()
    {
        // Restart polling for the new warehouse and fetch immediately.
        StartPolling();
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

